const PASSWORD_RESET_TTL_MINUTES = 15;
const QR_IMAGES = {
  starter: "",
  pro: ""
};
export default {
  async fetch(request, env) {
    try {
      await ensureSchema(env);
      const url = new URL(request.url);
      const path = url.pathname;

      if (request.method === "GET" && path === "/qr/starter") return qrImageResponse(request, env, QR_IMAGES.starter);
      if (request.method === "GET" && path === "/qr/pro") return qrImageResponse(request, env, QR_IMAGES.pro);

      if (path === "/api/health" && request.method === "GET") return json({ success:true, service:"CashGrow", status:"ok" });

      if (path === "/api/register" && request.method === "POST") return register(request, env);
      if (path === "/api/login" && request.method === "POST") return login(request, env);
      if (path === "/api/logout" && request.method === "POST") return logout(request, env);
      if (path === "/api/me" && request.method === "GET") return me(request, env);
      if (path === "/api/profile" && request.method === "POST") return profile(request, env);
      if (path === "/api/forgot-password" && request.method === "POST") return forgotPassword(request, env);
      if (path === "/api/reset-password" && request.method === "POST") return resetPassword(request, env);

      if (path === "/api/admin/login" && request.method === "POST") return adminLogin(request, env);
      if (path === "/api/admin/logout" && request.method === "POST") return adminLogout(request, env);
      if (path === "/api/admin/stats" && request.method === "GET") return adminStats(request, env);
      if (path === "/api/admin/payments" && request.method === "GET") return adminPendingPayments(request, env);
      if (path === "/api/admin/payment-action" && request.method === "POST") return adminPaymentAction(request, env);
      if (path === "/api/admin/cashbacks" && request.method === "GET") return adminCashbacks(request, env);
      if (path === "/api/admin/cashback-action" && request.method === "POST") return adminCashbackAction(request, env);
      if (path === "/api/admin/withdrawals" && request.method === "GET") return adminWithdrawals(request, env);
      if (path === "/api/admin/withdrawal-action" && request.method === "POST") return adminWithdrawalAction(request, env);

      if (path === "/api/create-order" && request.method === "POST") return createOrder(request, env);
      if (path === "/api/verify" && request.method === "POST") return verifyPayment(request, env);
      if (path === "/api/verify-qr" && request.method === "POST") return verifyQrPayment(request, env);

      if (path === "/api/dashboard" && request.method === "GET") return dashboard(request, env);
      if (path === "/api/referrals" && request.method === "GET") return referrals(request, env);
      if (path === "/api/transactions" && request.method === "GET") return transactions(request, env);
      if (path === "/api/purchases" && request.method === "GET") return purchases(request, env);
      if (path === "/api/withdraw" && request.method === "POST") return withdraw(request, env);
      if (path === "/api/withdrawals" && request.method === "GET") return withdrawals(request, env);

      if (request.method === "GET" && path === "/reset-password") return html(resetPage(url.searchParams.get("token") || ""));
      if (request.method === "GET" && path === "/admin") return html(adminPage());
      if (request.method === "GET") return html(home());

      return json({ success:false, message:"Not Found" },404);
    } catch (error) {
      console.error("CASHGROW_ERROR", error);
      return json({ success:false, message:"Server error", error:error?.message || String(error) },500);
    }
  }
};

const PRODUCTS = {
  starter:{ key:"starter", name:"Starter Bundle", amount:59900, reward:400 },
  pro:{ key:"pro", name:"Pro Bundle", amount:99900, reward:800 }
};
const MIN_WITHDRAWAL = 100000;

async function ensureSchema(env){
  if(!env.DB) throw new Error("D1 binding DB is missing");
  const stmts = [
    `CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      phone TEXT NOT NULL DEFAULT '',
      email TEXT NOT NULL DEFAULT '',
      referral_code TEXT UNIQUE,
      referred_by TEXT,
      wallet_balance INTEGER NOT NULL DEFAULT 0,
      password_hash TEXT,
      session_token TEXT,
      session_expires_at TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )`,
    `CREATE TABLE IF NOT EXISTS payments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      razorpay_order_id TEXT,
      razorpay_payment_id TEXT UNIQUE,
      product TEXT,
      amount INTEGER,
      status TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )`,
    `CREATE TABLE IF NOT EXISTS referrals (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      referrer_user_id INTEGER,
      referred_user_id INTEGER,
      payment_id TEXT,
      product TEXT,
      reward_amount INTEGER,
      status TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )`,
    `CREATE TABLE IF NOT EXISTS transactions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      type TEXT NOT NULL,
      amount INTEGER NOT NULL DEFAULT 0,
      direction TEXT NOT NULL DEFAULT 'credit',
      status TEXT NOT NULL DEFAULT 'completed',
      reference_id TEXT,
      description TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )`,
    `CREATE TABLE IF NOT EXISTS withdrawals (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      amount INTEGER NOT NULL,
      method TEXT,
      account_details TEXT,
      status TEXT NOT NULL DEFAULT 'pending',
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )`,
    `CREATE TABLE IF NOT EXISTS password_reset_tokens (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      token_hash TEXT NOT NULL UNIQUE,
      expires_at TEXT NOT NULL,
      used_at TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )`,
    `CREATE TABLE IF NOT EXISTS admin_sessions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      token TEXT NOT NULL UNIQUE,
      expires_at TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    )`
  ];
  for(const s of stmts) await env.DB.prepare(s).run();
  // Legacy builds stored referral_reward as rupees; normalize those known values to paise.
  await env.DB.prepare("UPDATE referrals SET reward_amount=reward_amount*100 WHERE reward_amount IN (400,800)").run();
}

function json(data,status=200,headers={}){
  return new Response(JSON.stringify(data),{status,headers:{"Content-Type":"application/json; charset=UTF-8",...headers}});
}
async function qrImageResponse(request,env,base64){
  if(!await currentUser(request,env)) return json({success:false,message:"Please login first."},401,{"Cache-Control":"no-store"});
  const binary=atob(base64);
  const bytes=Uint8Array.from(binary,char=>char.charCodeAt(0));
  return new Response(bytes,{headers:{"Content-Type":"image/jpeg","Cache-Control":"private, no-store"}});
}
function html(body,status=200){ return new Response(body,{status,headers:{"Content-Type":"text/html; charset=UTF-8"}}); }
function text(v){ return String(v ?? "").trim(); }
function money(paise){ return "\u20B9"+(Number(paise||0)/100).toFixed(2); }
function cookieToken(request){
  const c=request.headers.get("Cookie")||"";
  const m=c.match(/(?:^|;\s*)session_token=([^;]+)/);
  return m ? m[1] : null;
}
function setSession(token){
  return `session_token=${token}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=604800`;
}
function clearSession(){
  return "session_token=; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=0";
}
async function currentUser(request,env){
  const token=cookieToken(request);
  if(!token) return null;
  const now=new Date().toISOString();
  return env.DB.prepare(`SELECT id,name,phone,email,referral_code,referred_by,wallet_balance,created_at
    FROM users WHERE session_token=? AND session_expires_at>? LIMIT 1`).bind(token,now).first();
}
async function requireUser(request,env){
  const u=await currentUser(request,env);
  if(!u) throw Object.assign(new Error("Please login first"),{status:401});
  return u;
}
function safeError(error){ return error?.message || String(error); }

const hex = bytes => Array.from(bytes).map(b=>b.toString(16).padStart(2,"0")).join("");
const hexBytes = hexstr => {
  const out=new Uint8Array(hexstr.length/2);
  for(let i=0;i<out.length;i++) out[i]=parseInt(hexstr.slice(i*2,i*2+2),16);
  return out;
};
async function hashPassword(password){
  const salt=crypto.getRandomValues(new Uint8Array(16));
  const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);
  const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt,iterations:100000,hash:"SHA-256"},key,256);
  return `pbkdf2$100000$${hex(salt)}$${hex(new Uint8Array(bits))}`;
}
async function verifyPassword(password,stored){
  try{
    const p=stored.split("$");
    if(p.length!==4 || p[0]!=="pbkdf2") return false;
    const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);
    const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:hexBytes(p[2]),iterations:Number(p[1]),hash:"SHA-256"},key,256);
    const a=new Uint8Array(bits), b=hexBytes(p[3]);
    if(a.length!==b.length) return false;
    let d=0; for(let i=0;i<a.length;i++) d|=a[i]^b[i];
    return d===0;
  }catch{return false;}
}
async function referralCode(env){
  const chars="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  for(let n=0;n<20;n++){
    const bytes=crypto.getRandomValues(new Uint8Array(6));
    let s="CG"; for(const b of bytes) s+=chars[b%chars.length];
    const x=await env.DB.prepare("SELECT id FROM users WHERE referral_code=? LIMIT 1").bind(s).first();
    if(!x) return s;
  }
  throw new Error("Could not generate referral code");
}

async function register(request,env){
  try{
    const b=await request.json();
    const name=text(b.name), phone=text(b.phone).replace(/\D/g,""), email=text(b.email).toLowerCase(), password=String(b.password||"");
    const ref=text(b.referral_code).toUpperCase();
    if(!name||!phone||!email||!password) return json({success:false,message:"All fields are required."},400);
    if(password.length<6) return json({success:false,message:"Password must be at least 6 characters."},400);
    let referredBy=null;
    if(ref){
      const r=await env.DB.prepare("SELECT referral_code FROM users WHERE referral_code=? LIMIT 1").bind(ref).first();
      if(r)referredBy=r.referral_code;
    }
    const existing=await env.DB.prepare("SELECT * FROM users WHERE lower(email)=? OR phone=? LIMIT 1").bind(email,phone).first();
    const hash=await hashPassword(password);
    const token=crypto.randomUUID(), expires=new Date(Date.now()+7*86400000).toISOString();
    if(existing){
      if(existing.password_hash) return json({success:false,message:"Email or phone is already registered. Please login."},409);
      await env.DB.prepare("UPDATE users SET name=?,referred_by=COALESCE(NULLIF(referred_by,''),?),password_hash=?,session_token=?,session_expires_at=? WHERE id=?")
        .bind(name,referredBy,hash,token,expires,existing.id).run();
      return json({success:true,message:"Account activated successfully.",user:{...existing,name,password_hash:undefined}},200,{"Set-Cookie":setSession(token)});
    }
    const code=await referralCode(env);
    const result=await env.DB.prepare(`INSERT INTO users(name,phone,email,referral_code,referred_by,wallet_balance,password_hash,session_token,session_expires_at)
      VALUES(?,?,?,?,?,?,?,?,?)`).bind(name,phone,email,code,referredBy,0,hash,token,expires).run();
    return json({success:true,message:"Account created successfully.",user:{id:result.meta.last_row_id,name,phone,email,referral_code:code,referred_by:referredBy,wallet_balance:0}},200,{"Set-Cookie":setSession(token)});
  }catch(e){ return json({success:false,message:"Registration failed.",error:safeError(e)},500); }
}
async function login(request,env){
  try{
    const b=await request.json(), identifier=text(b.identifier).toLowerCase(), password=String(b.password||"");
    if(!identifier||!password) return json({success:false,message:"Email/phone and password are required."},400);
    const phone=identifier.replace(/\D/g,"");
    const u=await env.DB.prepare("SELECT * FROM users WHERE lower(email)=? OR phone=? LIMIT 1").bind(identifier,phone).first();
    if(!u) return json({success:false,message:"Account not found."},401);
    if(!u.password_hash) return json({success:false,message:"Please create/activate your account first."},400);
    if(!(await verifyPassword(password,u.password_hash))) return json({success:false,message:"Incorrect password."},401);
    const token=crypto.randomUUID(), expires=new Date(Date.now()+7*86400000).toISOString();
    await env.DB.prepare("UPDATE users SET session_token=?,session_expires_at=? WHERE id=?").bind(token,expires,u.id).run();
    return json({success:true,message:"Login successful.",user:{id:u.id,name:u.name,phone:u.phone,email:u.email,referral_code:u.referral_code,referred_by:u.referred_by,wallet_balance:u.wallet_balance||0}},200,{"Set-Cookie":setSession(token)});
  }catch(e){return json({success:false,message:"Login failed.",error:safeError(e)},500);}
}
async function logout(request,env){
  try{ const t=cookieToken(request); if(t) await env.DB.prepare("UPDATE users SET session_token=NULL,session_expires_at=NULL WHERE session_token=?").bind(t).run();
    return json({success:true,message:"Logged out."},200,{"Set-Cookie":clearSession()});
  }catch(e){return json({success:false,message:"Logout failed."},500);}
}
async function me(request,env){
  try{
    const u=await currentUser(request,env); if(!u) return json({success:false,loggedIn:false},401);
    const s=await env.DB.prepare("SELECT COUNT(*) referral_count,COALESCE(SUM(reward_amount),0) referral_earnings FROM referrals WHERE referrer_user_id=? AND status='credited'").bind(u.id).first();
    return json({success:true,loggedIn:true,user:{...u,referral_count:s?.referral_count||0,referral_earnings:s?.referral_earnings||0}});
  }catch(e){return json({success:false,loggedIn:false,error:safeError(e)},500);}
}
async function profile(request,env){
  try{
    const u=await requireUser(request,env), b=await request.json(), name=text(b.name), phone=text(b.phone).replace(/\D/g,"");
    if(!name||!phone) return json({success:false,message:"Name and phone are required."},400);
    await env.DB.prepare("UPDATE users SET name=?,phone=? WHERE id=?").bind(name,phone,u.id).run();
    return json({success:true,message:"Profile updated."});
  }catch(e){return json({success:false,message:safeError(e)},e.status||500);}
}

async function sha256Hex(value){
  const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(String(value)));
  return hex(new Uint8Array(digest));
}

async function sendResetEmail(env,to,resetUrl){
  if(!env.RESEND_API_KEY || !env.MAIL_FROM) throw new Error("Password reset email is not configured");
  const r=await fetch("https://api.resend.com/emails",{
    method:"POST",
    headers:{"Authorization":`Bearer ${env.RESEND_API_KEY}`,"Content-Type":"application/json"},
    body:JSON.stringify({
      from:env.MAIL_FROM,
      to:[to],
      subject:"CashGrow password reset",
      html:`<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;padding:24px"><h2>CashGrow Password Reset</h2><p>We received a request to reset your CashGrow password.</p><p>This link expires in 15 minutes and can be used only once.</p><p><a href="${resetUrl}" style="display:inline-block;padding:12px 18px;background:#0b3d2e;color:#fff;text-decoration:none;border-radius:8px">Reset Password</a></p><p style="color:#66756f;font-size:13px">If you did not request this, you can safely ignore this email.</p></div>`
    })
  });
  if(!r.ok){const t=await r.text();throw new Error(`Email delivery failed: ${t}`);}
}

async function forgotPassword(request,env){
  try{
    const b=await request.json();
    const email=text(b.email).toLowerCase();
    if(!email) return json({success:false,message:"Email is required."},400);
    const generic="If an account exists for this email, a password reset link has been sent.";
    const u=await env.DB.prepare("SELECT id FROM users WHERE lower(email)=? LIMIT 1").bind(email).first();
    if(!u) return json({success:true,message:generic});
    const recent=await env.DB.prepare("SELECT id FROM password_reset_tokens WHERE user_id=? AND created_at>datetime('now','-5 minutes') AND used_at IS NULL LIMIT 1").bind(u.id).first();
    if(recent) return json({success:true,message:generic});
    await env.DB.prepare("UPDATE password_reset_tokens SET used_at=datetime('now') WHERE user_id=? AND used_at IS NULL").bind(u.id).run();
    const raw=crypto.randomUUID()+"."+crypto.randomUUID();
    const tokenHash=await sha256Hex(raw);
    const expires=new Date(Date.now()+PASSWORD_RESET_TTL_MINUTES*60*1000).toISOString();
    await env.DB.prepare("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES(?,?,?)").bind(u.id,tokenHash,expires).run();
    const resetUrl=new URL(request.url);
    resetUrl.pathname="/reset-password";
    resetUrl.search="?token="+encodeURIComponent(raw);
    try{
      await sendResetEmail(env,email,resetUrl.toString());
    }catch(e){
      await env.DB.prepare("UPDATE password_reset_tokens SET used_at=datetime('now') WHERE token_hash=?").bind(tokenHash).run();
      throw e;
    }
    return json({success:true,message:generic});
  }catch(e){
    console.error("FORGOT_PASSWORD_ERROR",e);
    return json({success:false,message:"Password reset email could not be sent. Please try again later."},500);
  }
}

async function resetPassword(request,env){
  try{
    const b=await request.json();
    const token=text(b.token),password=String(b.password||"");
    if(!token||password.length<6)return json({success:false,message:"Valid reset token and a password of at least 6 characters are required."},400);
    const tokenHash=await sha256Hex(token);
    const row=await env.DB.prepare("SELECT id,user_id FROM password_reset_tokens WHERE token_hash=? AND used_at IS NULL AND expires_at>? LIMIT 1").bind(tokenHash,new Date().toISOString()).first();
    if(!row)return json({success:false,message:"This reset link is invalid or expired."},400);
    const hash=await hashPassword(password);
    await env.DB.prepare("UPDATE users SET password_hash=?,session_token=NULL,session_expires_at=NULL WHERE id=?").bind(hash,row.user_id).run();
    await env.DB.prepare("UPDATE password_reset_tokens SET used_at=datetime('now') WHERE id=? AND used_at IS NULL").bind(row.id).run();
    return json({success:true,message:"Password reset successfully. Please login with your new password."});
  }catch(e){return json({success:false,message:"Password reset failed."},500);}
}

function adminCookieToken(request){
  const c=request.headers.get("Cookie")||"";
  const m=c.match(/(?:^|;\s*)admin_token=([^;]+)/);
  return m?m[1]:null;
}
function setAdminSession(token){return `admin_token=${token}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=86400`;}
function clearAdminSession(){return "admin_token=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0";}
async function requireAdmin(request,env){
  if(!env.ADMIN_KEY)throw Object.assign(new Error("ADMIN_KEY is not configured"),{status:500});
  const token=adminCookieToken(request);
  if(!token)throw Object.assign(new Error("Admin login required"),{status:401});
  const row=await env.DB.prepare("SELECT id FROM admin_sessions WHERE token=? AND expires_at>? LIMIT 1").bind(token,new Date().toISOString()).first();
  if(!row)throw Object.assign(new Error("Admin login required"),{status:401});
  return row;
}
async function adminLogin(request,env){
  try{
    const b=await request.json();
    if(!env.ADMIN_KEY)return json({success:false,message:"Admin access is not configured. Add ADMIN_KEY in Cloudflare secrets."},500);
    if(!text(b.key)||text(b.key)!==String(env.ADMIN_KEY))return json({success:false,message:"Invalid admin key."},401);
    const token=crypto.randomUUID()+"."+crypto.randomUUID();
    const expires=new Date(Date.now()+24*60*60*1000).toISOString();
    await env.DB.prepare("INSERT INTO admin_sessions(token,expires_at) VALUES(?,?)").bind(token,expires).run();
    return json({success:true,message:"Admin login successful."},200,{"Set-Cookie":setAdminSession(token)});
  }catch(e){return json({success:false,message:"Admin login failed."},500);}
}
async function adminLogout(request,env){
  try{const t=adminCookieToken(request);if(t)await env.DB.prepare("DELETE FROM admin_sessions WHERE token=?").bind(t).run();return json({success:true},200,{"Set-Cookie":clearAdminSession()});}catch(e){return json({success:false},500);}
}
async function adminStats(request,env){
  try{
    await requireAdmin(request,env);
    const users=await env.DB.prepare("SELECT COUNT(*) count FROM users").first();
    const payments=await env.DB.prepare("SELECT COUNT(*) count,COALESCE(SUM(amount),0) amount FROM payments WHERE status='captured'").first();
    const pendingPayments=await env.DB.prepare("SELECT COUNT(*) count,COALESCE(SUM(amount),0) amount FROM payments WHERE status='pending' AND substr(razorpay_payment_id,1,3)='QR_'").first();
    const pending=await env.DB.prepare("SELECT COUNT(*) count,COALESCE(SUM(amount),0) amount FROM withdrawals WHERE status='pending'").first();
    const pendingCashback=await env.DB.prepare("SELECT COUNT(*) count,COALESCE(SUM(reward_amount),0) amount FROM referrals WHERE status='pending'").first();
    return json({success:true,stats:{
      users:Number(users?.count||0),
      payments:Number(payments?.count||0),
      payment_amount:Number(payments?.amount||0),
      pending_payments:Number(pendingPayments?.count||0),
      pending_payment_amount:Number(pendingPayments?.amount||0),
      pending_withdrawals:Number(pending?.count||0),
      pending_withdrawal_amount:Number(pending?.amount||0),
      pending_cashbacks:Number(pendingCashback?.count||0),
      pending_cashback_amount:Number(pendingCashback?.amount||0)
    }});
  }catch(e){return json({success:false,message:safeError(e)},e.status||500);}
}
async function adminPendingPayments(request,env){
  try{
    await requireAdmin(request,env);
    const r=await env.DB.prepare(`
      SELECT p.id,p.user_id,p.product,p.amount,p.razorpay_payment_id,p.created_at,
             u.name,u.phone,u.email
      FROM payments p
      LEFT JOIN users u ON u.id=p.user_id
      WHERE p.status='pending' AND substr(p.razorpay_payment_id,1,3)='QR_'
      ORDER BY p.id DESC LIMIT 200
    `).all();
    return json({success:true,items:r.results||[]});
  }catch(e){return json({success:false,message:safeError(e)},e.status||500);}
}

async function adminPaymentAction(request,env){
  try{
    await requireAdmin(request,env);
    const b=await request.json(),id=Number(b.id),action=text(b.action).toLowerCase();
    if(!id||!["approve","reject"].includes(action))return json({success:false,message:"Invalid payment action."},400);
    const payment=await env.DB.prepare(`
      SELECT p.*,u.referred_by
      FROM payments p
      LEFT JOIN users u ON u.id=p.user_id
      WHERE p.id=? AND p.status='pending' AND substr(p.razorpay_payment_id,1,3)='QR_'
      LIMIT 1
    `).bind(id).first();
    if(!payment)return json({success:false,message:"Pending QR payment not found or already reviewed."},404);

    if(action==="reject"){
      const result=await env.DB.prepare("UPDATE payments SET status='rejected' WHERE id=? AND status='pending'").bind(id).run();
      if(!result?.meta?.changes)return json({success:false,message:"Payment was already reviewed."},409);
      return json({success:true,message:"Payment rejected. The package was not activated."});
    }

    const product=PRODUCTS[payment.product];
    if(!product)return json({success:false,message:"Payment has an invalid package."},400);
    const referrer=payment.referred_by
      ? await env.DB.prepare("SELECT id FROM users WHERE referral_code=? LIMIT 1").bind(payment.referred_by).first()
      : null;
    const statements=[
      env.DB.prepare("UPDATE payments SET status='captured' WHERE id=? AND status='pending'").bind(id),
      env.DB.prepare(`INSERT INTO transactions(user_id,type,amount,direction,status,reference_id,description)
        SELECT p.user_id,'package_purchase',p.amount,'debit','completed',p.razorpay_payment_id,?
        FROM payments p
        WHERE p.id=? AND p.status='captured'
          AND NOT EXISTS (SELECT 1 FROM transactions t WHERE t.user_id=p.user_id AND t.type='package_purchase' AND t.reference_id=p.razorpay_payment_id)`)
        .bind(`Purchased ${product.name} via QR / UPI`,id)
    ];
    if(referrer&&referrer.id!==payment.user_id){
      const reward=product.reward*100;
      statements.push(
        env.DB.prepare(`INSERT INTO referrals(referrer_user_id,referred_user_id,product,reward_amount,status,payment_id)
          SELECT ?,p.user_id,p.product,?,'pending',p.razorpay_payment_id
          FROM payments p
          WHERE p.id=? AND p.status='captured'
            AND NOT EXISTS (SELECT 1 FROM referrals r WHERE r.payment_id=p.razorpay_payment_id)`)
          .bind(referrer.id,reward,id),
        env.DB.prepare(`INSERT INTO transactions(user_id,type,amount,direction,status,reference_id,description)
          SELECT ?, 'referral_reward', ?, 'credit', 'pending', p.razorpay_payment_id, ?
          FROM payments p
          WHERE p.id=? AND p.status='captured'
            AND EXISTS (SELECT 1 FROM referrals r WHERE r.payment_id=p.razorpay_payment_id AND r.status='pending')
            AND NOT EXISTS (SELECT 1 FROM transactions t WHERE t.user_id=? AND t.type='referral_reward' AND t.reference_id=p.razorpay_payment_id)`)
          .bind(referrer.id,reward,`Referral reward pending admin approval for ${product.name}`,id,referrer.id)
      );
    }
    const results=await env.DB.batch(statements);
    if(!results[0]?.meta?.changes)return json({success:false,message:"Payment was already reviewed."},409);
    const rewardMessage=referrer&&referrer.id!==payment.user_id
      ? ` A ₹${product.reward} referral reward is pending approval.`
      : "";
    return json({success:true,message:`Payment approved. ${product.name} is now active.${rewardMessage}`});
  }catch(e){return json({success:false,message:safeError(e)},e.status||500);}
}
