async function adminWithdrawalAction(request,env){
  try{
    await requireAdmin(request,env);
    const b=await request.json(),id=Number(b.id),action=text(b.action).toLowerCase();
    if(!id||!["paid","reject"].includes(action))return json({success:false,message:"Invalid withdrawal action."},400);
    const w=await env.DB.prepare("SELECT * FROM withdrawals WHERE id=? LIMIT 1").bind(id).first();
    if(!w)return json({success:false,message:"Withdrawal not found."},404);
    if(w.status!=="pending")return json({success:false,message:"Withdrawal is already processed."},409);
    const tx=await env.DB.prepare("SELECT id FROM transactions WHERE user_id=? AND type='withdrawal' AND status='pending' AND amount=? ORDER BY id DESC LIMIT 1").bind(w.user_id,w.amount).first();
    if(action==="paid"){
      const r=await env.DB.prepare("UPDATE withdrawals SET status='paid' WHERE id=? AND status='pending'").bind(id).run();
      if(!r?.meta?.changes)return json({success:false,message:"Withdrawal is already processed."},409);
      if(tx)await env.DB.prepare("UPDATE transactions SET status='completed',reference_id=? WHERE id=?").bind(String(id),tx.id).run();
      return json({success:true,message:"Withdrawal marked as paid. Confirm external payout has been completed."});
    }
    const r=await env.DB.prepare("UPDATE withdrawals SET status='rejected' WHERE id=? AND status='pending'").bind(id).run();
    if(!r?.meta?.changes)return json({success:false,message:"Withdrawal is already processed."},409);
    await env.DB.prepare("UPDATE users SET wallet_balance=wallet_balance+? WHERE id=?").bind(w.amount,w.user_id).run();
    if(tx)await env.DB.prepare("UPDATE transactions SET status='rejected',reference_id=? WHERE id=?").bind(String(id),tx.id).run();
    await env.DB.prepare("INSERT INTO transactions(user_id,type,amount,direction,status,reference_id,description) VALUES(?,?,?,?,?,?,?)").bind(w.user_id,"withdrawal_refund",w.amount,"credit","completed",String(id),"Rejected withdrawal refunded to wallet").run();
    return json({success:true,message:"Withdrawal rejected and amount refunded to wallet."});
  }catch(e){return json({success:false,message:safeError(e)},e.status||500);}
}

