      <button onclick="closeQrPay()" style="position:absolute;top:16px;right:16px;background:#f0f4f2;border:0;width:34px;height:34px;border-radius:50%;font-size:18px;font-weight:bold;cursor:pointer;color:#333;">&times;</button>
      
